window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-621a0a467698c908"]={"versions": [{"id": "FIG-621a0a467698c908", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>). Das Diagramm beschreibt die logische Prüfsequenz beim Empfang/De-Serialisieren transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node)</li>\n<li>Entscheidungsknoten (Decision Nodes):</li>\n<li><code>Profile == PXXm</code></li>\n<li><code>extractProtocolHeaderFields == NULL</code></li>\n<li><code>csTransactionHandle == NULL</code></li>\n<li>Endzustände (Activity Final Nodes):</li>\n<li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten ohne Beschriftung bzw. Standard-Final-Node)</li>\n<li>Erfolgreicher Abschluss (<code>return TRUE</code>)</li>\n<li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten und prüft, ob das konfigurierte Profil <code>Profile == PXXm</code> entspricht.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wird die Prüfung übersprungen und direkt der Endzustand <code>return TRUE</code> erreicht.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob die Funktionsreferenz/Konfiguration <code>extractProtocolHeaderFields == NULL</code> ist:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall/Prüfung fehlgeschlagen).</li>\n<li>Bei <code>[FALSE]</code> geht der Fluss zur nächsten Bedingung über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>csTransactionHandle == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall).</li>\n<li>Bei <code>[FALSE]</code> terminiert der Ablauf im regulären Erfolgs-Endzustand <code>return TRUE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation bei profilbasierten Methodenaufrufen bzw. Header-Extraktionen (<code>PXXm</code>). Software-Entwickler müssen sicherstellen, dass bei aktivem Profil <code>PXXm</code> sowohl <code>extractProtocolHeaderFields</code> als auch <code>csTransactionHandle</code> gültig initialisiert bzw. ungleich <code>NULL</code> konfiguriert sind, andernfalls wird die Transformation mit Fehler beendet.</p>"}, {"id": "FIG-766a52eb7ef70146", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>) mit Legende der Kommunikationstypen. Das Diagramm beschreibt die logische Prüfsequenz beim Empfang transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node)</li>\n<li>Entscheidungsknoten (Decision Nodes, farbcodiert für „All types“):</li>\n<li><code>Profile == PXXm</code></li>\n<li><code>extractProtocolHeaderFields == NULL</code></li>\n<li><code>csTransactionHandle == NULL</code></li>\n<li>Endzustände (Activity Final Nodes):</li>\n<li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten)</li>\n<li>Erfolgreicher Abschluss (<code>return TRUE</code>)</li>\n<li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code></li>\n<li>Legendenkasten <code>Communication Types</code> mit Farbzuordnungen für:</li>\n<li>All types (Beige)</li>\n<li>Sender/Receiver (Hellgrün)</li>\n<li>Publisher/Subscriber (Grün)</li>\n<li>C/S: Server (Hellblau)</li>\n<li>C/S: Client (Rosa)</li>\n<li>Signal to Service (Gelb)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten und prüft, ob das konfigurierte Profil <code>Profile == PXXm</code> entspricht.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wird die Prüfung übersprungen und direkt der Endzustand <code>return TRUE</code> erreicht.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob die Funktionsreferenz/Konfiguration <code>extractProtocolHeaderFields == NULL</code> ist:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall/Prüfung fehlgeschlagen).</li>\n<li>Bei <code>[FALSE]</code> geht der Fluss zur nächsten Bedingung über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>csTransactionHandle == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall).</li>\n<li>Bei <code>[FALSE]</code> terminiert der Ablauf im regulären Erfolgs-Endzustand <code>return TRUE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation bei profilbasierten Methodenaufrufen bzw. Header-Extraktionen (<code>PXXm</code>). Software-Entwickler müssen sicherstellen, dass bei aktivem Profil <code>PXXm</code> sowohl <code>extractProtocolHeaderFields</code> als auch <code>csTransactionHandle</code> gültig initialisiert bzw. ungleich <code>NULL</code> konfiguriert sind, andernfalls wird die Transformation mit Fehler beendet.</p>"}, {"id": "FIG-655dd39043c755a4", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>) mit Legende der Kommunikationstypen. Das Diagramm beschreibt die logische Prüfsequenz beim Empfang transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node)</li>\n<li>Entscheidungsknoten (Decision Nodes, farbcodiert für „All types“):</li>\n<li><code>Profile == PXXm</code></li>\n<li><code>extractProtocolHeaderFields == NULL</code></li>\n<li><code>csTransactionHandle == NULL</code></li>\n<li>Endzustände (Activity Final Nodes):</li>\n<li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten)</li>\n<li>Erfolgreicher Abschluss (<code>return TRUE</code>)</li>\n<li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code></li>\n<li>Legendenkasten <code>Legend</code> mit Farbzuordnungen für:</li>\n<li>All types (Beige)</li>\n<li>Sender/Receiver (Hellgrün)</li>\n<li>Publisher/Subscriber (Grün)</li>\n<li>C/S: Server (Hellblau)</li>\n<li>C/S: Client (Rosa)</li>\n<li>Signal to Service (Gelb)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten und prüft, ob das konfigurierte Profil <code>Profile == PXXm</code> entspricht.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wird die Prüfung übersprungen und direkt der Endzustand <code>return TRUE</code> erreicht.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob die Funktionsreferenz/Konfiguration <code>extractProtocolHeaderFields == NULL</code> ist:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall/Prüfung fehlgeschlagen).</li>\n<li>Bei <code>[FALSE]</code> geht der Fluss zur nächsten Bedingung über.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>csTransactionHandle == NULL</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall).</li>\n<li>Bei <code>[FALSE]</code> terminiert der Ablauf im regulären Erfolgs-Endzustand <code>return TRUE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation bei profilbasierten Methodenaufrufen bzw. Header-Extraktionen (<code>PXXm</code>). Software-Entwickler müssen sicherstellen, dass bei aktivem Profil <code>PXXm</code> sowohl <code>extractProtocolHeaderFields</code> als auch <code>csTransactionHandle</code> gültig initialisiert bzw. ungleich <code>NULL</code> konfiguriert sind, andernfalls wird die Transformation mit Fehler beendet.</p>"}, {"id": "FIG-2bc86ea52b670f6a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>) mit Legende der Kommunikationstypen. Das Diagramm beschreibt die logische Prüfsequenz beim Empfang transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node)</li>\n<li>Entscheidungsknoten (Decision Nodes, farbcodiert für „All types“):</li>\n<li><code>Profile == PXXm</code></li>\n<li><code>extractProtocolHeaderFields == NULL</code></li>\n<li>Endzustände (Activity Final Nodes):</li>\n<li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten)</li>\n<li>Erfolgreicher Abschluss (<code>return TRUE</code>)</li>\n<li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code></li>\n<li>Legendenkasten <code>Legend</code> mit Farbzuordnungen für:</li>\n<li>All types (Beige)</li>\n<li>Sender/Receiver (Hellgrün)</li>\n<li>Publisher/Subscriber (Grün)</li>\n<li>C/S: Server (Hellblau)</li>\n<li>C/S: Client (Rosa)</li>\n<li>Signal to Service (Gelb)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten und prüft, ob <code>Profile == PXXm</code> gilt.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wechselt der Kontrollfluss direkt zum Endzustand <code>return TRUE</code>.</li>\n<li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob <code>extractProtocolHeaderFields == NULL</code> gilt:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerabbruch).</li>\n<li>Bei <code>[FALSE]</code> terminiert der Ablauf direkt im regulären Endzustand <code>return TRUE</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation beim Profil <code>PXXm</code>. Bei konfiguriertem Profil <code>PXXm</code> ist ausschließlich das Vorhandensein der Header-Extraktionsfunktion (<code>extractProtocolHeaderFields != NULL</code>) Voraussetzung für die Fortsetzung; eine Prüfung auf <code>csTransactionHandle</code> findet an dieser Stelle nicht statt.</p>"}], "trans": [{"from": "FIG-621a0a467698c908", "to": "FIG-766a52eb7ef70146", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Oben links wurde ein Legendenkasten („Communication Types“) ergänzt, der Farbcodierungen für Kommunikationstypen aufführt (All types, Sender/Receiver, Publisher/Subscriber, C/S: Server, C/S: Client, Signal to Service).</li>\n<li>Die Entscheidungsknoten im Aktivitätsdiagramm sind gemäß dem Farbcode für „All types“ eingefärbt.</li>\n</ul>"}, {"from": "FIG-766a52eb7ef70146", "to": "FIG-655dd39043c755a4", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Die Überschrift des Legendenkastens wurde von „Communication Types“ zu „Legend“ geändert.</li>\n</ul>"}, {"from": "FIG-655dd39043c755a4", "to": "FIG-2bc86ea52b670f6a", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Der Entscheidungsknoten <code>csTransactionHandle == NULL</code> und dessen ausgehende Kanten (<code>[TRUE]</code> zum linken Endzustand, <code>[FALSE]</code> zum Endzustand <code>return TRUE</code>) wurden entfernt.</li>\n<li>Der Zweig <code>[FALSE]</code> der Bedingung <code>extractProtocolHeaderFields == NULL</code> führt nun direkt zum Endzustand <code>return TRUE</code>.</li>\n</ul>"}]};
